import * as E from './engine.js';
import {buildStudy} from './study-engine.js';
import {evenlySample} from './chart-stats.js';

export function createStudyView({t,esc,label,val,fmt,color,field,select,btn}) {
 const text=(x,y,s,attrs='')=>`<text x="${x}" y="${y}" ${attrs}>${esc(s)}</text>`;
 const cut=(s,n=18)=>String(s).length>n?String(s).slice(0,n-1)+'…':String(s);
 const name=g=>g===undefined?t('全部记录','All records'):val(g);
 const svg=(id,w,h,body,title)=>`<svg id="${id}" class="study-svg" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="group" aria-label="${esc(title)}"><title>${esc(title)}</title><rect width="${w}" height="${h}" fill="white"/>${body}</svg>`;
 const note=s=>`<p class="study-note">${s}</p>`;
 const finding=(big,body)=>`<div class="study-finding"><strong>${esc(big)}</strong><p>${esc(body)}</p></div>`;
 const keyLabel=(s,g)=>s.config.dimension?name(g.key):t('全部记录','All records');
 const legend=(items,key='key')=>`<div class="study-legend">${items.map((g,i)=>`<span><i style="background:${color[g.colorIndex??i%8]}"></i>${esc(name(g[key]))}</span>`).join('')}</div>`;
 const exportButton=id=>btn('exportStudyChart',t('导出图形','Export SVG'),'download','small ghost',`data-chart="${id}"`);
 const card=(title,id,chart,body,subtitle='')=>`<section class="card study-section"><div class="study-section-head"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${exportButton(id)}</div><div class="study-evidence"><div class="study-plot">${chart}</div><aside class="study-reading">${body}</aside></div></section>`;
 const ticks=(min,max,n=4)=>Array.from({length:n+1},(_,i)=>min+(max-min)*i/n);
 const bounds=values=>{const s=E.describe(values);return [s.min??0,s.max===s.min?(s.max??0)+1:s.max??1];};
 function comparePlot(s) {
  const numeric=Boolean(s.config.metric),groups=s.shown,W=680,L=70,R=22,T=28,B=68,H=330;
  if(!numeric){const max=Math.max(1,...groups.map(g=>g.total)),h=groups.length*38+56;return svg('studyComparison',W,h,groups.map((g,i)=>{const y=20+i*38;return text(145,y+17,cut(keyLabel(s,g)),'text-anchor="end"')+`<rect x="160" y="${y}" width="${g.total/max*430}" height="24" rx="4" fill="${color[g.colorIndex]}"/>`+text(170+g.total/max*430,y+17,g.total);}).join(''),t('类别记录数','Records by category'));}
  if(!s.stats.count)return `<div class="study-unavailable">${t('这个指标没有有效数值，请选择另一个指标。','This metric has no valid numeric values. Choose another metric.')}</div>`;
  const [min,max]=bounds(groups.flatMap(g=>g.count?[g.min,g.max]:[])),y=v=>H-B-(v-min)/(max-min)*(H-T-B),step=(W-L-R)/Math.max(1,groups.length);
  let body=ticks(min,max).map(v=>`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e8e8f4"/>`+text(L-10,y(v)+4,fmt(v,1),'text-anchor="end"')).join('')+text(L,15,cut(label(s.config.metric),35));
  if(s.time){const valid=groups.map((g,i)=>({...g,i})).filter(g=>g.count),points=valid.map(g=>`${L+step*(g.i+.5)},${y(g.mean)}`);body+=`<polyline points="${points.join(' ')}" fill="none" stroke="${color[0]}" stroke-width="3"/>`+valid.map(g=>`<circle cx="${L+step*(g.i+.5)}" cy="${y(g.mean)}" r="4" fill="${color[0]}"><title>${esc(g.key)}: ${fmt(g.mean,2)} · n=${g.count}</title></circle>`).join('');}
  else groups.forEach((g,i)=>{const x=L+step*(i+.5),c=color[g.colorIndex],width=Math.min(54,step*.45);if(!g.count)return;body+=`<line x1="${x}" x2="${x}" y1="${y(g.low)}" y2="${y(g.high)}" stroke="${c}" stroke-width="2"/><path d="M${x-width/3} ${y(g.low)}h${width*2/3}M${x-width/3} ${y(g.high)}h${width*2/3}" stroke="${c}" stroke-width="2"/><rect x="${x-width/2}" y="${y(g.q3)}" width="${width}" height="${Math.max(2,y(g.q1)-y(g.q3))}" fill="${c}25" stroke="${c}" stroke-width="2"/><path d="M${x-width/2} ${y(g.median)}h${width}" stroke="${c}" stroke-width="3"/>`;
   evenlySample(g.records.filter(r=>E.numeric(r.row[s.config.metric])),65).forEach((r,j)=>{const cx=x+Math.sin(j*127.1)*width*.58;body+=`<circle data-act="inspectRow" data-row="${r.index}" role="button" tabindex="0" aria-label="${esc(t('查看记录 ','Inspect row ')+(r.index+1))}" cx="${cx}" cy="${y(r.row[s.config.metric])}" r="2.7" fill="${c}" opacity=".4"><title>#${r.index+1} · ${esc(keyLabel(s,g))}: ${r.row[s.config.metric]}</title></circle>`;});
  });
  groups.forEach((g,i)=>{if(s.time&&i%Math.max(1,Math.ceil(groups.length/6))!==0)return;const x=L+step*(i+.5);body+=text(x,H-40,cut(keyLabel(s,g),Math.max(5,Math.floor(step/12))),'text-anchor="middle"')+text(x,H-20,'n='+g.count,'text-anchor="middle"');});
  return svg('studyComparison',W,H,body,s.time?t('各时段指标均值','Mean by period'):t('各组指标分布与真实观测','Group distributions and observations'))+note(s.time?t('每点为该时段均值。未观测时段没有补零；连线仅连接已有时段。','Each point is a period mean. Unobserved periods are not filled with zero; lines connect observed periods.'):t('箱体覆盖中间 50% 观测，横线为中位数；须线为 1.5×IQR 内极值。每组最多显示 65 个真实点，点击可看记录。','Boxes cover the middle 50%; the line is the median and whiskers reach observations within 1.5×IQR. Up to 65 real points per group; click to inspect.'));
 }
 function compareReading(s){
  if(!s.config.metric){const g=s.groups.toSorted((a,b)=>b.total-a.total)[0],tied=s.groups.filter(c=>c.total===g?.total).length>1;return finding(t(`${name(g?.key)}${tied?'并列':''}记录最多`,`${tied?'Joint most':'Most'} records: ${name(g?.key)}`),t(`共 ${g?.total??0} 条，占全部记录的 ${fmt((g?.total??0)/s.total*100,1)}%；全部记录分为 ${s.groups.length} 组。`,`${g?.total??0} records, ${fmt((g?.total??0)/s.total*100,1)}% of all rows; ${s.groups.length} groups in total.`));}
  let lead='';
  if(s.time){const g=s.shown.filter(g=>g.count),first=g[0],last=g.at(-1);lead=first&&last?finding(t('时段均值变化','Change in period means'),t(`${first.key} 至 ${last.key}，均值从 ${fmt(first.mean,2)} 变为 ${fmt(last.mean,2)}，变化 ${fmt(last.mean-first.mean,2)}。有效样本量分别为 ${first.count} 和 ${last.count}。`,`${first.key} to ${last.key}: mean ${fmt(first.mean,2)} to ${fmt(last.mean,2)}, a change of ${fmt(last.mean-first.mean,2)}. Valid sample sizes: ${first.count} and ${last.count}.`)):'';}
  else if(s.top&&s.bottom&&s.top.id!==s.bottom.id){const overlap=Math.max(s.top.q1,s.bottom.q1)<=Math.min(s.top.q3,s.bottom.q3);lead=finding(t(`${name(s.top.key)}的均值最高`,`Highest mean: ${name(s.top.key)}`),t(`均值 ${fmt(s.top.mean,2)}，比${name(s.bottom.key)}高 ${fmt(s.top.mean-s.bottom.mean,2)}。两组中间 50% 的区间${overlap?'存在':'没有'}重叠，分别为 ${fmt(s.top.q1,1)}–${fmt(s.top.q3,1)} 和 ${fmt(s.bottom.q1,1)}–${fmt(s.bottom.q3,1)}。`,`Mean ${fmt(s.top.mean,2)}, ${fmt(s.top.mean-s.bottom.mean,2)} above ${name(s.bottom.key)}. Their middle-50% intervals ${overlap?'overlap':'do not overlap'}: ${fmt(s.top.q1,1)}–${fmt(s.top.q3,1)} and ${fmt(s.bottom.q1,1)}–${fmt(s.bottom.q3,1)}.`));}
  else lead=finding(t('指标分布范围','Metric distribution'),t(`有效值 ${s.stats.count} 个，中位数 ${fmt(s.stats.median,2)}，范围 ${fmt(s.stats.min,2)}–${fmt(s.stats.max,2)}。`,`${s.stats.count} valid values, median ${fmt(s.stats.median,2)}, range ${fmt(s.stats.min,2)}–${fmt(s.stats.max,2)}.`));
  return lead+`<div class="study-number-list">${s.shown.slice(0,8).map(g=>`<div><span><i style="background:${color[g.colorIndex]}"></i>${esc(keyLabel(s,g))}</span><b>${fmt(g.mean,1)}<small>${t('均值','mean')} · n=${g.count}</small></b></div>`).join('')}</div>`+note(t(`统计使用全部有效值；${s.total-s.stats.count} 条缺少当前指标。`, `Statistics use all valid values; ${s.total-s.stats.count} rows lack this metric.`));
 }
 function relationPlot(s){
  const W=680,H=370,L=70,R=20,T=28,B=88,{metric,related,dimension}=s.config,[xmin,xmax]=bounds(s.paired.map(r=>r.row[related])),[ymin,ymax]=bounds(s.paired.map(r=>r.row[metric])),x=v=>L+(v-xmin)/(xmax-xmin)*(W-L-R),y=v=>H-B-(v-ymin)/(ymax-ymin)*(H-B-T);
  let body=ticks(ymin,ymax).map(v=>`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e8e8f4"/>`+text(L-10,y(v)+4,fmt(v,1),'text-anchor="end"')).join('')+ticks(xmin,xmax).map(v=>text(x(v),H-B+23,fmt(v,1),'text-anchor="middle"')).join('');
  const colors=new Map(s.shown.map(g=>[g.id,color[g.colorIndex]]));
  body+=evenlySample(s.paired,1200).map(r=>{const c=s.time?color[0]:colors.get(JSON.stringify(dimension?r.row[dimension]??null:null))||'#b1adbe';return `<circle data-act="inspectRow" data-row="${r.index}" role="button" tabindex="0" aria-label="${esc(t('查看记录 ','Inspect row ')+(r.index+1))}" cx="${x(r.row[related])}" cy="${y(r.row[metric])}" r="3.5" fill="${c}" opacity=".58"><title>#${r.index+1} · ${esc(label(related))}: ${r.row[related]} · ${esc(label(metric))}: ${r.row[metric]}</title></circle>`;}).join('');
  body+=text(L,15,cut(label(metric),35))+text(W-R,H-B+43,cut(label(related),35),'text-anchor="end"');
  if(!s.time&&dimension)s.shown.forEach((g,i)=>{const xx=L+(i%4)*148,yy=H-25+Math.floor(i/4)*20;body+=`<circle cx="${xx}" cy="${yy}" r="4" fill="${color[g.colorIndex]}"/>`+text(xx+10,yy+4,cut(name(g.key),13));});
  return svg('studyRelation',W,H+(!s.time&&s.shown.length>4?20:0),body,t('关联指标与目标指标的散点','Related metric versus target metric'))+note(t(`有效配对 ${s.paired.length} / ${s.total} 条；最多绘制 1,200 个真实点，相关系数使用全部有效配对。`,`Valid pairs: ${s.paired.length} / ${s.total}. At most 1,200 real points are drawn; correlations use every valid pair.`)+(!s.time&&s.groups.length>8?t(' 灰色点为其余分组。',' Gray points represent other groups.'):''));
 }
 function relationReading(s){
  const r=s.correlation,direction=r===null?t('当前无法计算相关系数','Correlation is undefined'):t(`整体${r>=0?'正':'负'}相关，r = ${fmt(r,3)}`,`Overall ${r>=0?'positive':'negative'} correlation, r = ${fmt(r,3)}`);
  const within=s.groups.map(g=>g.correlation).filter(E.numeric),details=!s.time&&s.config.dimension&&within.length?t(`${within.length} 个分组的相关系数范围为 ${fmt(Math.min(...within),3)}–${fmt(Math.max(...within),3)}；其中 ${within.filter(v=>Math.abs(v)<Math.abs(r)).length} 组的相关强度低于整体。`,`${within.length} groups have correlations from ${fmt(Math.min(...within),3)} to ${fmt(Math.max(...within),3)}; ${within.filter(v=>Math.abs(v)<Math.abs(r)).length} have weaker associations than the overall value.`):t(`共有 ${s.paired.length} 条成对有效观测，占全部记录的 ${fmt(s.paired.length/s.total*100,1)}%。`,`${s.paired.length} valid pairs, ${fmt(s.paired.length/s.total*100,1)}% of all observations.`);
  return finding(direction,r===null?t('有效配对不足或某个字段为常量。','Too few valid pairs or a constant field.'):details)+(!s.time&&s.config.dimension?`<div class="study-number-list">${s.shown.map(g=>`<div><span><i style="background:${color[g.colorIndex]}"></i>${esc(name(g.key))}</span><b>${fmt(g.correlation,3)}<small>r · n=${g.pairs}</small></b></div>`).join('')}</div>`:'')+note(t('Pearson 衡量线性关联；相关不代表因果。','Pearson measures linear association; correlation is not causation.'));
 }
 function strataPlot(s){
  const W=680,L=150,R=28,T=40,rowH=65,H=T+s.strata.length*rowH+75,stats=s.strata.flatMap(g=>g.cells.map(c=>c.mean).filter(E.numeric)),[min,max]=bounds(stats),x=v=>L+(v-min)/(max-min)*(W-L-R),width=W-L-R;
  if(!s.config.metric){const peak=Math.max(1,...s.strata.flatMap(g=>g.cells.map(c=>c.total))),cw=width/Math.max(1,s.splitLevels.length),h=60+s.strata.length*44+38;let heat=s.splitLevels.map((c,j)=>text(L+(j+.5)*cw,25,cut(name(c.key),14),'text-anchor="middle"')).join('');s.strata.forEach((g,i)=>{const y=43+i*44;heat+=text(L-12,y+23,cut(keyLabel(s,g),15),'text-anchor="end"')+g.cells.map((c,j)=>`<rect x="${L+j*cw+2}" y="${y}" width="${cw-4}" height="38" rx="4" fill="#eae6fb"/><rect x="${L+j*cw+2}" y="${y}" width="${cw-4}" height="38" rx="4" fill="#6352d5" opacity="${c.total/peak*.75}"/>`+text(L+(j+.5)*cw,y+24,c.total,'text-anchor="middle"')).join('');});return svg('studyStrata',W,h,heat,t('两个类别的交叉记录数','Cross-category record counts'))+note(t('每格是一个类别组合的记录数，颜色越深记录越多。','Each cell counts a category combination. Darker cells contain more records.'));}
  let body=ticks(min,max).map(v=>text(x(v),23,fmt(v,1),'text-anchor="middle"')).join('');
  s.strata.forEach((g,i)=>{const y=T+i*rowH;body+=text(L-14,y+14,cut(keyLabel(s,g),14),'text-anchor="end"');const valid=g.cells.filter(c=>E.numeric(c.mean));if(s.config.metric&&valid.length>1)body+=`<line x1="${x(Math.min(...valid.map(c=>c.mean)))}" x2="${x(Math.max(...valid.map(c=>c.mean)))}" y1="${y+9}" y2="${y+9}" stroke="#c8c3dc" stroke-width="3"/>`;
   body+=text(L-14,y+39,t('占比','share'),'text-anchor="end" font-size="10"');
   let offset=0;g.cells.forEach((c,j)=>{const fraction=c.total/g.total;body+=(s.config.metric&&E.numeric(c.mean)?`<circle cx="${x(c.mean)}" cy="${y+9}" r="6" fill="${color[j]}" stroke="white" stroke-width="1.5"><title>${esc(name(g.key)+' / '+name(c.key))}: ${fmt(c.mean,2)} · n=${c.count}</title></circle>`:'')+`<rect x="${L+offset*width}" y="${y+27}" width="${fraction*width}" height="16" fill="${color[j]}" opacity=".85"><title>${esc(name(c.key))}: ${c.total} / ${g.total} (${fmt(fraction*100,1)}%)</title></rect>`+(fraction>.12?text(L+(offset+fraction/2)*width,y+39,fmt(fraction*100,1)+'%','text-anchor="middle" fill="white" font-size="10"'):'');offset+=fraction;});
   if(offset<1)body+=`<rect x="${L+offset*width}" y="${y+27}" width="${(1-offset)*width}" height="14" fill="#c5c6d3"><title>${t('其余类别','Other levels')}: ${fmt((1-offset)*100,1)}%</title></rect>`;
  });
  s.splitLevels.forEach((c,i)=>{const xx=35+i*165,yy=H-25;body+=`<circle cx="${xx}" cy="${yy}" r="4" fill="${color[i]}"/>`+text(xx+10,yy+4,cut(name(c.key),15));});
  return svg('studyStrata',W,H,body,t('分层均值与记录构成','Stratified means and record composition'))+note(t('上排圆点读顶部均值刻度；下排细条独立表示 0–100% 的组内占比。缺失也计入；灰色为未单列类别。','Dots use the mean scale at the top; strips independently show 0–100% of each group. Missing levels are included; gray represents levels not shown individually.'));
 }
 function strataReading(s){
  if(!s.config.metric){const pairs=s.groups.flatMap(g=>s.splitAll.map(level=>({group:g.key,key:level.key,count:g.records.filter(r=>JSON.stringify(r.row[s.config.split]??null)===level.id).length}))).sort((a,b)=>b.count-a.count),top=pairs[0];return finding(t('最多的类别组合','Most frequent combination'),t(name(top?.group)+' × '+name(top?.key)+'：'+(top?.count??0)+' 条记录。',name(top?.group)+' × '+name(top?.key)+': '+(top?.count??0)+' records.'))+note(t('交叉计数使用全部记录，缺失类别也保留。图中最多展示 8 个行类别与 4 个列类别；导出包含所有组合。','Cross counts use all rows, including missing levels. The plot shows up to 8 row levels and 4 column levels; export includes every combination.'));}
  const summary=s.config.metric&&s.top&&s.comparable.length?finding(t('分层均值比较结果','Stratified mean comparison'),t(`${name(s.top.key)}在 ${s.comparable.length} 个可比较的非缺失分层中，有 ${s.retainedLead} 个仍保持最高均值。`,`${name(s.top.key)} retains the highest mean in ${s.retainedLead} of ${s.comparable.length} comparable non-missing strata.`)):finding(t('分层样本构成','Stratum composition'),t(`共 ${s.splitAll.length} 个分层类别，${s.total} 条记录。当前没有包含至少两个有效分组的非缺失分层。`,`${s.splitAll.length} stratum levels across ${s.total} rows. No non-missing stratum contains at least two valid groups.`));
  return summary+`<div class="study-number-list">${s.splitLevels.map((c,i)=>`<div><span><i style="background:${color[i]}"></i>${esc(name(c.key))}</span><b>${fmt(c.total)}<small>${t('条记录','records')} · ${fmt(c.total/s.total*100,1)}%</small></b></div>`).join('')}</div>`+note(t('这里只描述当前观测，不自动推断显著性或因果。悬停圆点可看均值和有效样本数。','These are descriptions of the observations, not significance or causal claims. Hover dots for means and valid sample sizes.'));
 }
 function render(rows,cols,spec,sample,dataset){
  const s=buildStudy(rows,cols,spec,sample),{metric,dimension,related,split,interval}=s.config,nums=s.fields.numbers.map(k=>[k,label(k)]),dims=[...s.fields.categories,...s.fields.dates].map(k=>[k,label(k)]),optional=t('不加入','None');
  const title=s.time&&!metric?t('时段记录分布分析','Records over time'):s.time?t(`${label(metric)} · 时间趋势分析`,`${label(metric)} · Time trend analysis`):metric&&dimension?t(`${label(metric)} · ${label(dimension)}分组分析`,`${label(metric)} · Analysis by ${label(dimension)}`):metric?t(`${label(metric)} · 分布与关联分析`,`${label(metric)} · Distribution and association`):t('类别构成与交叉分析','Category composition and cross analysis');
  let html=`<div class="study-workspace"><section class="study-brief"><div class="study-title"><h2>${esc(title)}</h2><p>${esc(dataset)} · ${fmt(s.total)} ${t('条当前记录','working records')} ${sample?'· Palmer Penguins':''}</p></div><div class="study-fields">${dims.length?field(t('比较维度','Compare by'),select('study-dimension',dims,dimension)):''}${nums.length?field(t('分析指标','Analysis metric'),select('study-metric',nums,metric)):''}${nums.length>1?field(t('关联指标','Related metric'),select('study-related',[['',optional],...nums.filter(([k])=>k!==metric)],related)):''}${s.fields.categories.filter(k=>k!==dimension).length?field(t('分层核对','Break down by'),select('study-split',[['',optional],...s.fields.categories.filter(k=>k!==dimension).map(k=>[k,label(k)])],split)):''}${s.time?field(t('时间粒度','Interval'),select('study-interval',[['day',t('日','Day')],['week',t('周','Week')],['month',t('月','Month')],['year',t('年','Year')]],interval)):''}</div><p class="study-route">${t('分组分布','Group distributions')}${related?' <span>→</span> '+t('相关性分析','Correlation analysis'):''}${split?' <span>→</span> '+t('分层比较','Stratified comparison'):''}<small>${t('调整字段，整组分析同步更新','Changing fields updates the whole analysis')}</small></p></section>`;
  if(!rows.length)return html+`<div class="card card-pad">${t('当前没有记录。请恢复原始数据或添加数据集。','No working records. Restore original data or add a dataset.')}</div></div>`;
  html+=card(s.time?t(`${metric?label(metric):t('记录数','Records')}时间趋势`,`${metric?label(metric):'Records'} over time`):metric?t(`${label(metric)}分组分布`,`${label(metric)} distribution by group`):t(`${label(dimension)}频数分布`,`${label(dimension)} frequency distribution`),'studyComparison',comparePlot(s),compareReading(s),metric?(s.time?t('时段均值 · 有效样本量','Period means · Valid sample sizes'):t('中位数 · 四分位区间 · 原始观测','Medians · Interquartile ranges · Observations')):t('类别频数 · 缺失类别单列','Category counts · Explicit missing category'));
  if(related&&metric){html+=s.paired.length?card(t(`${label(related)}与${label(metric)}相关性分析`,`${label(related)} and ${label(metric)} correlation`),'studyRelation',relationPlot(s),relationReading(s),t('整体 Pearson 相关 · 分组内相关','Overall Pearson correlation · Within-group correlation')):`<p class="study-unavailable">${t('两个指标没有成对有效值，已略过关联图。其他分析仍保留。','These metrics have no valid pairs, so the association plot is omitted. Other analyses remain available.')}</p>`;}
  if(split&&s.shown.length)html+=card(metric?t(`${label(split)}分层比较`,`${label(split)} stratified comparison`):t(`${label(dimension)}与${label(split)}交叉分布`,`${label(dimension)} and ${label(split)} cross distribution`),'studyStrata',strataPlot(s),strataReading(s),metric?t('分层指标均值 · 样本构成占比','Stratum means · Sample composition'):t('类别组合 · 交叉记录数','Category combinations · Cross counts'));
  html+=`<div class="study-footer"><p>${t(`图中覆盖 ${s.shownRows} / ${s.total} 条记录${s.groups.length>s.shown.length?'；类别图最多 8 组，时间图最多 48 个有效时段':''}。统计与导出包含全部分组。`,`Plots cover ${s.shownRows} / ${s.total} rows${s.groups.length>s.shown.length?'; category plots show up to 8 groups, time plots up to 48 valid periods':''}. Statistics and export include every group.`)}</p>${btn('exportStudy',t('导出分析数据 CSV','Export analysis data CSV'),'download','small')}</div></div>`;
  return html;
 }
 return {render};
}
